head.script:
scwin.screenId = "jldinf20000p";

///////// 1. 변수 및 선언 영역 /////////

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin._popupWindow = undefined;
scwin.type = undefined;

///////// 2. 초기화 영역 /////////

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 초기화 함수(init_*)를 데이터 의존성 순서로 순차 실행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam(); // 1) 파라미터 수신 (dma_pageContext 확보)
        scwin.init_rowCopy(); // 2) searchRadio 표시값 복사
        scwin.init_attrReals(); // 3) 페이징 요약(ul_68) 동적 렌더
        scwin.init_conds(); // 4) 결과 영역(if_result) 표시 조건 평가
        scwin.init_datefmt_cal_stdCdGrntStartDd(); // 5) 코드부여일 시작 달력 포맷 점검
        scwin.init_datefmt_cal_stdCdGrntEndDd(); // 6) 코드부여일 종료 달력 포맷 점검
        scwin.init_pageBody(); // 7) 코드부여일 초기값 설정 (파라미터 확정 후)
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf20000p.onpageload' });
    }
};

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_attrReals
 * @description dma_page(total/currentPage/pageCount) 값이 하나라도 있으면 "총 n건 (x/y)" 페이징 요약 HTML 을 만들어 ul_68 에 렌더한다(모두 비어 있으면 빈 문자열).
 * @returns {void}
 * @hidden N
 * @example scwin.init_attrReals();
 */
scwin.init_attrReals = function () {
    const readPage = function (key) {
        return String($c.data.readValue("dma_page", key, { silent: true }));
    };
    const attrReals = [{
        childId: "ul_68",
        attr: "__html",
        fn: function () {
            const vals = [readPage("total"), readPage("currentPage"), readPage("pageCount")];
            const hasValue = vals.some(function (v) {
                return String(v == null ? '' : v).trim() !== '';
            });
            if (!hasValue) { return ''; }
            return "총 <strong id=\"totPage\">" + vals[0] + "</strong>건 <span id=\"totPage1\">(" + vals[1] + "/" + vals[2] + ")</span>";
        }
    }];
    $c.util.applyAttrReals(attrReals);
};

// 런타임 분기 평가 — 공용 $c.util.evalConds (화면은 조건 바인딩 목록만 보유)
// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_conds
 * @description dma_pageContext.result 값 존재 여부로 페이지 내비게이터 영역(if_result)의 표시 조건을 평가한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_conds();
 */
scwin.init_conds = function () {
    const binds = [{
        id: "if_result",
        fn: function () {
            const result = $c.data.readValue("dma_pageContext", "result", { ctx: true, label: "result" });
            return (!(String(result == null ? '' : result).length === 0));
        }
    }];
    $c.util.evalConds(binds);
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_rowCopy
 * @description dma_pageContext.searchRadio 값을 hidden 입력(ipt_searchRadio) 표시값으로 복사한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_rowCopy();
 */
scwin.init_rowCopy = function () {
    const rowCopies = [{
        childId: "ipt_searchRadio",
        fn: function () {
            return String(String($c.data.readValue("dma_pageContext", "searchRadio", { silent: true })));
        }
    }];
    $c.data.copyRows(rowCopies);
};

/**
 * @method
 * @name init_datefmt_cal_stdCdGrntStartDd
 * @description 코드부여일 시작 달력(cal_stdCdGrntStartDd)의 날짜 포맷(yyyyMMdd)을 점검한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_datefmt_cal_stdCdGrntStartDd();
 */
scwin.init_datefmt_cal_stdCdGrntStartDd = function () {
    $c.date.checkCalendarFormat("cal_stdCdGrntStartDd", "yyyyMMdd");
};

/**
 * @method
 * @name init_datefmt_cal_stdCdGrntEndDd
 * @description 코드부여일 종료 달력(cal_stdCdGrntEndDd)의 날짜 포맷(yyyyMMdd)을 점검한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_datefmt_cal_stdCdGrntEndDd();
 */
scwin.init_datefmt_cal_stdCdGrntEndDd = function () {
    $c.date.checkCalendarFormat("cal_stdCdGrntEndDd", "yyyyMMdd");
};

/**
 * @method
 * @name init_pageBody
 * @description 화면 전환 파라미터(std_cd_grnt_start_dd/std_cd_grnt_end_dd)가 있으면 코드부여일 시작·종료 달력에 초기값을 설정한다(8자리면 날짜 포맷 적용).
 * @returns {void}
 * @hidden N
 * @example scwin.init_pageBody();
 */
scwin.init_pageBody = function () {
    try {
        const startDdRaw = $c.data.readValue("dma_pageContext", "std_cd_grnt_start_dd", { ctx: true, soft: true, label: "std_cd_grnt_start_dd" });
        const startDdStr = String(startDdRaw == null ? '' : startDdRaw);
        const std_cd_grnt_start_dd = startDdStr.indexOf('$' + '{') >= 0 ? '' : startDdStr;
        const endDdRaw = $c.data.readValue("dma_pageContext", "std_cd_grnt_end_dd", { ctx: true, soft: true, label: "std_cd_grnt_end_dd" });
        const endDdStr = String(endDdRaw == null ? '' : endDdRaw);
        const std_cd_grnt_end_dd = endDdStr.indexOf('$' + '{') >= 0 ? '' : endDdStr;
        if (std_cd_grnt_start_dd !== "") {
            const calStart = $c.util.getComponent('cal_stdCdGrntStartDd');
            if (std_cd_grnt_start_dd.length === 8) {
                calStart.setValue($c.date.dateFormat(std_cd_grnt_start_dd));
            } else {
                calStart.setValue(std_cd_grnt_start_dd);
            }
        }
        if (std_cd_grnt_end_dd !== "") {
            const calEnd = $c.util.getComponent('cal_stdCdGrntEndDd');
            if (std_cd_grnt_end_dd.length === 8) {
                calEnd.setValue($c.date.dateFormat(std_cd_grnt_end_dd));
            } else {
                calEnd.setValue(std_cd_grnt_end_dd);
            }
        }
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000p.onpageload' });
    }
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 $c.data.recvParamData, 이름 고정 "paramData").
 * @returns {void}
 * @hidden N
 * @example scwin.init_recvParam();
 */
scwin.init_recvParam = function () {
    $c.data.recvParamData('dma_pageContext');
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name btn_appDate2_onclick
 * @description [3개월] 버튼 클릭 — 코드부여일 검색 기간을 오늘 기준 최근 3개월로 설정한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_appDate2 ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_appDate2_onclick = function (e) {
    try {
        scwin.fn_appDate2('stdCdGrntStartDd', 'stdCdGrntEndDd', 3);
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000p.btn_appDate2_onclick' });
    }
};

/**
 * @event
 * @name btn_appDate2_2_onclick
 * @description [6개월] 버튼 클릭 — 코드부여일 검색 기간을 오늘 기준 최근 6개월로 설정한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_appDate2_2 ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_appDate2_2_onclick = function (e) {
    try {
        scwin.fn_appDate2('stdCdGrntStartDd', 'stdCdGrntEndDd', 6);
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000p.btn_appDate2_2_onclick' });
    }
};

/**
 * @event
 * @name btn_appDate2_3_onclick
 * @description [1년] 버튼 클릭 — 코드부여일 검색 기간을 오늘 기준 최근 12개월로 설정한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_appDate2_3 ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_appDate2_3_onclick = function (e) {
    try {
        scwin.fn_appDate2('stdCdGrntStartDd', 'stdCdGrntEndDd', 12);
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000p.btn_appDate2_3_onclick' });
    }
};

/**
 * @event
 * @name btn_search_onclick
 * @description [조회] 버튼 클릭 — 검색 조건으로 표준코드 채권 목록을 조회한다(fn_search(1)).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_search ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_search_onclick = async function (e) {
    try {
        await scwin.fn_search(1);
    } catch (_ex) {
        await $c.exception.handleError(_ex, { context: 'jldinf20000p.btn_search_onclick' });
    }
};

/**
 * @event
 * @name dataTb_oncellclick
 * @description 목록 셀 클릭 — 시장 구분(mktNm)이 '14'가 아니면 해당 표준코드의 유가증권 상세 팝업(onPopupCode)을 연다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 열 인덱스
 * @param {String} columnId 클릭한 열 id
 * @returns {void}
 * @hidden N
 * @example (dataTb ev:oncellclick 바인딩으로 자동 호출)
 */
scwin.dataTb_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        const r = dl && dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["mktNm"] !== '14') {
            await scwin.onPopupCode(r["mktNm"], r["stdCd"]);
            return;
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'dataTb.oncellclick' });
    }
};

/**
 * @event
 * @name btn_window_onclick
 * @description [닫기] 버튼 클릭 — 현재 팝업을 닫는다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_window ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_window_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000p.btn_window_onclick' });
    }
};

/**
 * @event
 * @name btn_window_onfocus
 * @description [닫기] 버튼 포커스 — 포커스 표시를 남기지 않도록 즉시 blur 처리한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_window ev:onfocus 바인딩으로 자동 호출)
 */
scwin.btn_window_onfocus = function (e) {
    try {
        const selfEl = (e && (e.element || e.target || e.srcElement)) || this;
        selfEl.blur();
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000p.btn_window_onfocus' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name tx_onPopupCode
 * @description 표준코드 상세 팝업 조회를 서버에 요청한다(dma_onPopupCodeReq → dlt_result). 응답 실패 시 서버 메시지를 알린다.
 * @returns {Object} executeDynamic 응답 객체(resObj, 예외 시 null)
 * @hidden N
 * @example const res = await scwin.tx_onPopupCode();
 */
scwin.tx_onPopupCode = async function () {
    const sbmOptions = {
        id: "tx_onPopupCode",
        method: "post",
        action: "/srch/srch.do?method=srchPopup",
        ref: "dma_onPopupCodeReq",
        target: "dlt_result=body",
        isProcessMsg: false
    };
    let res = null;
    try {
        res = await $c.sbm.executeDynamic(sbmOptions);
    } catch (_e) {
        await $c.exception.handleError(_e, { notify: 'none', context: "jldinf20000p.tx_onPopupCode" });
        return null;
    }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) {
            await $c.win.alert(res.responseJSON.message);
        }
        return res;
    }
    return res;
};

/**
 * @method
 * @name tx_fn_search
 * @description 표준코드 채권 목록 조회를 서버에 요청한다(dma_searchReq → dlt_result). 응답 실패 시 서버 메시지를 알린다.
 * @returns {Object} executeDynamic 응답 객체(resObj, 예외 시 null)
 * @hidden N
 * @example const res = await scwin.tx_fn_search();
 */
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/srch/srch.do?method=srchPopupList",
        ref: "dma_searchReq",
        target: "dlt_result=body",
        isProcessMsg: false
    };
    let res = null;
    try {
        res = await $c.sbm.executeDynamic(sbmOptions);
    } catch (_e) {
        await $c.exception.handleError(_e, { notify: 'none', context: "jldinf20000p.tx_fn_search" });
        return null;
    }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) {
            await $c.win.alert(res.responseJSON.message);
        }
        return res;
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////

// 표준 API 조합으로 새로 작성한 검사 함수
/**
 * @method
 * @name fn_appDate2
 * @description 종료일을 서버 오늘 날짜로, 시작일을 그로부터 months 개월 전으로 계산해 시작·종료 달력(cal_ 또는 ipt_ 접두 컴포넌트)에 설정한다.
 * @param {String} startId 시작일 컴포넌트 id 접미(name)
 * @param {String} endId 종료일 컴포넌트 id 접미(name)
 * @param {Number} months 소급할 개월 수
 * @returns {void}
 * @hidden N
 * @example scwin.fn_appDate2('stdCdGrntStartDd', 'stdCdGrntEndDd', 3);
 */
scwin.fn_appDate2 = function (startId, endId, months) {
    try {
        const endDate = $c.date.getServerDateTime();
        const startDate = $c.date.addMonth(endDate, -Number(months || 0));
        const resolveComp = function (nm) {
            return $c.util.getComponent('cal_' + nm) || $c.util.getComponent('ipt_' + nm) || $c.util.getComponent(String(nm));
        };
        const startComp = resolveComp(String(startId));
        if (startComp && startComp.setValue) { startComp.setValue(startDate); }
        const endComp = resolveComp(String(endId));
        if (endComp && endComp.setValue) { endComp.setValue(endDate); }
    } catch (_e) {
        $c.exception.handleError(_e, { notify: 'none', context: 'fn_appDate2' });
    }
};

/**
 * @method
 * @name dateSetting
 * @description dma_pageContext.curDate 기준 1·3·6개월 전 날짜(yyyyMMdd)를 계산해 dma_hiddenStore(ipt_hdOneDate/ipt_hdThreeDate/ipt_hdSixDate)에 저장한다.
 * @returns {void}
 * @hidden N
 * @example scwin.dateSetting();
 */
scwin.dateSetting = function () {
    const curDateRaw = $c.data.readValue("dma_pageContext", "curDate", { ctx: true, soft: true, label: "curDate" });
    const curDateStr = String(curDateRaw == null ? '' : curDateRaw);
    const curDate = curDateStr.indexOf('$' + '{') >= 0 ? '' : curDateStr;
    const curYY = curDate.substring(0, 4);
    const curMM = curDate.substring(4, 6);
    const curDD = curDate.substring(6, 8);
    const intCurYY = Number(curYY);
    const intCurMM = Number(curMM);
    let bfOneYY = "";
    let bfOneMM = "";
    let calMM = intCurMM - 1;
    if (calMM < 0) {
        bfOneYY = intCurYY - 1;
        bfOneMM = 12 + calMM;
    } else {
        bfOneYY = intCurYY;
        bfOneMM = calMM;
    }
    let bfThreeYY = "";
    let bfThreeMM = "";
    calMM = intCurMM - 3;
    if (calMM < 0) {
        bfThreeYY = intCurYY - 1;
        bfThreeMM = 12 + calMM;
    } else {
        bfThreeYY = intCurYY;
        bfThreeMM = calMM;
    }
    let bfSixYY = "";
    let bfSixMM = "";
    calMM = intCurMM - 6;
    if (calMM < 0) {
        bfSixYY = intCurYY - 1;
        bfSixMM = 12 + calMM;
    } else {
        bfSixYY = intCurYY;
        bfSixMM = calMM;
    }
    const oneDD = new Date(bfOneYY, bfOneMM, curDD);
    const threeDD = new Date(bfThreeYY, bfThreeMM, curDD);
    const sixDD = new Date(bfSixYY, bfSixMM, curDD);
    if (Number(bfOneMM) < 10) {
        bfOneMM = "0" + bfOneMM;
    }
    if (Number(bfThreeMM) < 10) {
        bfThreeMM = "0" + bfThreeMM;
    }
    if (Number(bfSixMM) < 10) {
        bfSixMM = "0" + bfSixMM;
    }
    const oneD = (Number(oneDD.getMonth()) < 10) ? ("0" + oneDD.getMonth()) : oneDD.getMonth();
    const ThD = (Number(threeDD.getMonth()) < 10) ? ("0" + threeDD.getMonth()) : threeDD.getMonth();
    const SxD = (Number(sixDD.getMonth()) < 10) ? ("0" + sixDD.getMonth()) : sixDD.getMonth();
    const oneDt = (Number(oneDD.getDate()) < 10) ? ("0" + oneDD.getDate()) : oneDD.getDate();
    const ThDt = (Number(threeDD.getDate()) < 10) ? ("0" + threeDD.getDate()) : threeDD.getDate();
    const SxDt = (Number(sixDD.getDate()) < 10) ? ("0" + sixDD.getDate()) : sixDD.getDate();
    const bfOneDate = oneDD.getFullYear() + oneD + oneDt;
    const bfThreeDate = threeDD.getFullYear() + ThD + ThDt;
    const bfSixDate = sixDD.getFullYear() + SxD + SxDt;
    const hiddenStore = $c.util.getComponent('dma_hiddenStore');
    if (hiddenStore && hiddenStore.set) {
        hiddenStore.set('ipt_hdOneDate', bfOneDate);
    } else {
        console.warn('[sdd] hiddenStore 부재: ipt_hdOneDate');
    }
    if (hiddenStore && hiddenStore.set) {
        hiddenStore.set('ipt_hdThreeDate', bfThreeDate);
    } else {
        console.warn('[sdd] hiddenStore 부재: ipt_hdThreeDate');
    }
    if (hiddenStore && hiddenStore.set) {
        hiddenStore.set('ipt_hdSixDate', bfSixDate);
    } else {
        console.warn('[sdd] hiddenStore 부재: ipt_hdSixDate');
    }
};

/**
 * @method
 * @name onPopupCode
 * @description 표준코드 상세 조회 팝업(jldinf20000p, winPop)을 열고, 시장 구분(type)·표준코드를 dma_hiddenStore 에 저장한 뒤 popup_form action 을 구분별 조회 URL 로 설정한다.
 * @param {String} type 시장 구분 코드(122 는 12 로 치환)
 * @param {String} ipt_stdCd 표준코드
 * @returns {void}
 * @hidden N
 * @example await scwin.onPopupCode(mktNm, stdCd);
 */
scwin.onPopupCode = async function (type, ipt_stdCd) {
    const fm = (document.popup_form || { elements: [] });
    const onPopupCodeReq = $c.util.getComponent("dma_onPopupCodeReq");
    scwin._popupWindow = $c.win.openPopup("/jldinf20000p/jldinf20000p.xml", {
        id: "winPop",
        scrollbars: true,
        resizable: false,
        width: "1000",
        height: "670",
        type: "pageFramePopup"
    }, (onPopupCodeReq ? onPopupCodeReq.getJSON() : {}));
    if (type === "122") {
        type = "12";
    }
    const hiddenStore = $c.util.getComponent('dma_hiddenStore');
    if (hiddenStore && hiddenStore.set) {
        hiddenStore.set('ipt_stdcdType', type);
    } else {
        console.warn('[sdd] hiddenStore 부재: ipt_stdcdType');
    }
    if (hiddenStore && hiddenStore.set) {
        hiddenStore.set('ipt_stdCd', ipt_stdCd);
    } else {
        console.warn('[sdd] hiddenStore 부재: ipt_stdCd');
    }
    fm.action = "/srch/srch.do?method=srchPopup" + type;
};

/**
 * @method
 * @name open_corp_cd
 * @description JLDINF20000p 폼을 넘겨 발행기관 검색 팝업(fn_popupCorpSearch2)을 연다.
 * @param {String} item_id 결과를 받을 코드 입력 항목 id
 * @param {String} item_nm 결과를 받을 명칭 입력 항목 id
 * @returns {void}
 * @hidden N
 * @example scwin.open_corp_cd("isurCd", "isurNm");
 */
scwin.open_corp_cd = function (item_id, item_nm) {
    const formName = (document.JLDINF20000p || { elements: [] });
    fn_popupCorpSearch2(formName, item_id, item_nm);
};

/**
 * @method
 * @name fn_search
 * @description 검색 라디오·상장 구분 체크 목록(list_cd3)을 수집해 dma_hiddenStore.ipt_listCd 에 저장하고, 폼 action 설정·로딩 표시 후 목록 조회(tx_fn_search)를 실행한다.
 * @param {Number|String} idx 조회할 페이지 인덱스(문자열 '1' 이면 pageIndex 를 1로 리셋)
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_search(1);
 */
scwin.fn_search = async function (idx) {
    // 규칙 19 — 원본 라디오 그룹(input[name=ipt_searchRadio])은 전환 시 hidden 컴포넌트(ipt_searchRadio)로
    // 대체되어 선택값을 컴포넌트 API 로 읽는다.
    const srIdx = $c.util.getComponent('ipt_searchRadio').getValue();
    let ck_stat_cd = "";
    // 규칙 19 — 상장 구분 체크박스(name=list_cd3)는 전환 마크업에 대응 컴포넌트가 없어(실측 0건)
    // 표준 DOM 조회로 전환한다(체크 항목 부재 시 기존과 동일하게 빈 문자열 유지).
    const ckArr = document.querySelectorAll('input[name="list_cd3"]:checked');
    const statLeng = ckArr.length;
    if (statLeng > 0) {
        for (let i = 0; i < statLeng; i++) {
            ck_stat_cd = ck_stat_cd + ((ck_stat_cd === "") ? "'" + ckArr[i].value + "'" : ",'" + ckArr[i].value + "'");
        }
    }
    const hiddenStore = $c.util.getComponent('dma_hiddenStore');
    if (hiddenStore && hiddenStore.set) {
        hiddenStore.set('ipt_listCd', ck_stat_cd);
    } else {
        console.warn('[sdd] hiddenStore 부재: ipt_listCd');
    }
    const frm = (document.JLDINF20000p || { elements: [] });
    if (idx === '1') {
        // 규칙 19 — hidden pageIndex(ipt_pageIndex, ref: dma_onPopupCodeReq.pageIndex)를 컴포넌트 API 로 설정한다.
        $c.util.getComponent('ipt_pageIndex').setValue("1");
    }
    frm.action = "/srch/srch.do?method=srchPopupList";
    frm.target = "_self";
    blockLoading();
    await scwin.tx_fn_search();
};

/**
 * @event
 * @name krxpage_pagenavigator_127_onclick
 * @description 페이지 내비게이터 클릭 — 선택한 페이지 인덱스로 목록을 조회한다.
 * @param {Number} index 선택한 페이지 번호
 * @returns {void}
 * @hidden N
 * @example (krxpage_pagenavigator_127 ev:onclick 바인딩으로 자동 호출)
 */
scwin.krxpage_pagenavigator_127_onclick = function (index) {
    scwin.fn_search(index);
};
